-- FreshPrep PostgreSQL baseline. All amounts in INR paise, weight in grams.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('SUPERADMIN','ADMIN','CUSTOMER_ADMIN','CUSTOMER_BUYER','CUSTOMER_VIEWER','OPERATOR','QC','DISPATCH','FINANCE')), PRIMARY KEY(organization_id,user_id,role));
CREATE TABLE kitchens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, address text NOT NULL, zone_code text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(id,organization_id));
CREATE TABLE vegetables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE preparation_methods (code text PRIMARY KEY CHECK(code IN ('DICED','CHOPPED','SLICED','GRATED','SHREDDED','JULIENNE','PEELED')), display_name text NOT NULL);
INSERT INTO preparation_methods(code,display_name) VALUES ('DICED','Diced'),('CHOPPED','Chopped'),('SLICED','Sliced'),('GRATED','Grated'),('SHREDDED','Shredded'),('JULIENNE','Julienne'),('PEELED','Peeled');
CREATE TABLE product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vegetable_id uuid NOT NULL REFERENCES vegetables(id), method_code text NOT NULL REFERENCES preparation_methods(code), sku text NOT NULL UNIQUE, size_kind text NOT NULL CHECK(size_kind IN ('numeric','label')), size_number numeric(10,2), size_unit text, size_label text, image_url text NOT NULL, price_paise_per_kg integer NOT NULL CHECK(price_paise_per_kg>=0), minimum_grams integer NOT NULL CHECK(minimum_grams>0), increment_grams integer NOT NULL CHECK(increment_grams>0), active boolean NOT NULL DEFAULT true, CONSTRAINT correct_size CHECK((size_kind='numeric' AND size_number>0 AND size_unit IN ('mm','cm') AND size_label IS NULL) OR (size_kind='label' AND size_number IS NULL AND size_unit IS NULL AND size_label IN ('fine','medium','coarse','thin','thick'))));
CREATE TABLE delivery_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), zone_code text NOT NULL, label text NOT NULL, start_minute integer NOT NULL CHECK(start_minute BETWEEN 0 AND 1439), end_minute integer NOT NULL CHECK(end_minute BETWEEN 1 AND 1440), cutoff_day_offset integer NOT NULL CHECK(cutoff_day_offset BETWEEN 0 AND 7), cutoff_minute integer NOT NULL CHECK(cutoff_minute BETWEEN 0 AND 1439), capacity_orders integer NOT NULL CHECK(capacity_orders>0), active boolean NOT NULL DEFAULT true, CHECK(end_minute>start_minute));
CREATE TABLE slot_blackouts (slot_id uuid NOT NULL REFERENCES delivery_slots(id), delivery_date date NOT NULL, reason text NOT NULL, PRIMARY KEY(slot_id,delivery_date));
CREATE TABLE slot_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slot_id uuid NOT NULL REFERENCES delivery_slots(id), delivery_date date NOT NULL, order_id uuid NOT NULL UNIQUE, UNIQUE(slot_id,delivery_date,order_id));
CREATE INDEX slot_reservation_lookup ON slot_reservations(slot_id,delivery_date);
CREATE TABLE recurring_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), kitchen_id uuid NOT NULL, slot_id uuid NOT NULL REFERENCES delivery_slots(id), frequency text NOT NULL CHECK(frequency IN ('DAILY','WEEKLY')), weekdays integer[] NOT NULL DEFAULT '{}', start_date date NOT NULL, end_date date, state text NOT NULL DEFAULT 'ACTIVE' CHECK(state IN ('ACTIVE','PAUSED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(kitchen_id,organization_id) REFERENCES kitchens(id,organization_id), CHECK(end_date IS NULL OR end_date>=start_date), CHECK(frequency='DAILY' OR cardinality(weekdays)>0));
CREATE TABLE recurring_items (schedule_id uuid NOT NULL REFERENCES recurring_schedules(id) ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES product_variants(id), grams integer NOT NULL CHECK(grams>0), PRIMARY KEY(schedule_id,variant_id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), kitchen_id uuid NOT NULL, slot_id uuid NOT NULL REFERENCES delivery_slots(id), delivery_date date NOT NULL, source_schedule_id uuid REFERENCES recurring_schedules(id), state text NOT NULL DEFAULT 'CONFIRMED' CHECK(state IN ('CONFIRMED','IN_PRODUCTION','QC_PASSED','PACKED','DISPATCHED','DELIVERED','CANCELLED','EXCEPTION')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(kitchen_id,organization_id) REFERENCES kitchens(id,organization_id));
ALTER TABLE slot_reservations ADD CONSTRAINT slot_reservation_order_fk FOREIGN KEY(order_id) REFERENCES orders(id);
CREATE TABLE order_items (order_id uuid NOT NULL REFERENCES orders(id), variant_id uuid NOT NULL REFERENCES product_variants(id), grams integer NOT NULL CHECK(grams>0), price_paise_per_kg integer NOT NULL CHECK(price_paise_per_kg>=0), PRIMARY KEY(order_id,variant_id));
CREATE TABLE recurring_occurrences (schedule_id uuid NOT NULL REFERENCES recurring_schedules(id), delivery_date date NOT NULL, slot_id uuid NOT NULL REFERENCES delivery_slots(id), order_id uuid UNIQUE REFERENCES orders(id), state text NOT NULL CHECK(state IN ('CREATED','BLOCKED','SKIPPED')), reason text, PRIMARY KEY(schedule_id,delivery_date,slot_id));
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, organization_id uuid REFERENCES organizations(id), actor_id uuid REFERENCES users(id), event_type text NOT NULL, subject_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
